import csv
ref = {}
with open('/app/reference/metservice_et0_2025.csv') as f:
    for row in csv.DictReader(f):
        ref[(row['station_id'], row['date'])] = float(row['et0_mm_day'])
our = {}
with open('/app/output/et0.csv') as f:
    for row in csv.DictReader(f):
        our[(row['station_id'], row['date'])] = float(row['et0_mm_day'])
max_diff = 0
for k, v in ref.items():
    d = abs(v - our[k])
    max_diff = max(max_diff, d)
    if d > 0.05:
        print(f'  {k}: ref={v} our={our[k]} diff={d:.3f}')
print(f'Reference rows: {len(ref)}, max abs diff: {max_diff:.4f}')
print(f'Total output rows: {len(our)}')
"
